package za.co.innaesim.backup.model;

import java.util.ArrayList;
import java.util.List;

import lombok.Data;
import lombok.ToString;

/**
 * What one job backs up, and its output settings: a database connection, or folders for {@code type: folder}.
 *
 * Getters and setters are generated by Lombok, so they don't appear in this documentation.
 */
@Data
public class AppConfig {
    private String type;
    private String host;
    private Integer port;
    private String name;
    private String user;
    @ToString.Exclude
    private String password;
    /** MongoDB only: the database the user authenticates against. */
    private String authDb;
    private String outputDir;
    private Boolean compress;
    private String filepattern = "{db}_{date}{ext}";
    /** Folder jobs only: the folders to back up, as absolute paths. */
    private List<String> paths = new ArrayList<>();
    /** Folder jobs only: glob patterns to leave out. */
    private List<String> excludes = new ArrayList<>();

    /** Creates empty settings with the default file pattern. */
    public AppConfig() {}
}
